using System.Text.Json;
using GamePulse.Api.Services;
using GamePulse.Api.Models.Nfl;
var checks=0;
void Check(bool ok,string label){checks++;if(!ok)throw new Exception(label);}
NflTeam Team(string id)=>new(id,null,id,null,null,null,null);
NflGame Game(string id,int week,string home,string away,int? hs,int? aws,string phase="REG",string status="final")=>new(id,2025,phase,"Week "+week,week,"2025-09-01",null,home,away,hs,aws,status,null);
NflStat Stat(string gid,int week,string tid,string opp,int att,int cmp,int? yds,string? pid=null,string phase="REG")=>new(2025,phase,week,gid,tid,opp,JsonSerializer.SerializeToElement(new{attempts=att,completions=cmp,passing_yards=yds,passing_tds=1,passing_interceptions=0}),pid,"Player","QB");
var games=new[]{Game("g1",1,"A","B",21,7),Game("g2",2,"C","A",7,7),Game("future",3,"A","B",null,null,status:"scheduled"),Game("post",20,"A","B",3,0,"POST")};
var teams=new[]{Team("A"),Team("B"),Team("C")};
var score=NflSeasonInsights.Scores("season",games.Take(3),"A");
Check(score.ScheduledGames==3&&score.CompletedGames==2&&score.ScoredGames==2,"Only final games scored");
Check(score.Wins==1&&score.Losses==0&&score.Ties==1&&score.WinPercentage==.75,"Ties are half wins");
Check(score.PointsFor==28&&score.PointsAgainst==14&&score.Differential==14&&score.PointsPerGame==14,"Score orientation and rates");
Check(NflSeasonInsights.Scores("empty",[],"A").PointsFor==null,"No empty fabricated scoring totals");
Check(NflSeasonInsights.Scores("missing",[Game("missing",1,"A","B",null,1)],"A").PointsFor==null,"Unknown final score propagates");
var player=new NflPlayer("p","Player","QB",["A","C"],null,null);
var rows=new[]{Stat("g1",1,"A","B",10,7,100,"p"),Stat("g2",2,"C","A",20,12,80,"p"),Stat("post",20,"A","B",2,1,10,"p","POST")};
var coverage=JsonSerializer.SerializeToElement(new{missingCompletedTeamGames=1});
var p=NflSeasonInsights.Profile(2025,player,teams,games,rows,coverage,"REG",null);
Check(p.Groups["passing"]!.Totals["passing_yards"]==180&&p.Groups["passing"]!.Totals["attempts"]==30,"Player season sums");
Check(Math.Abs(p.Groups["passing"]!.Rates["completionPercentage"]!.Value-1900.0/30)<1e-12,"Completion percentage from summed components");
Check(p.Groups["passing"]!.TeamContributions.Length==2&&p.Groups["passing"]!.Games==2,"Traded split and distinct games");
Check(p.Groups["passing"]!.Rank==null&&p.Groups["passing"]!.Value==null,"Profile does not invent global rank");
Check(p.Groups["rushing"]==null&&p.Groups["receiving"]==null,"No fabricated category activity");
var a=NflSeasonInsights.Profile(2025,player,teams,games,rows,coverage,"REG","A");
var c=NflSeasonInsights.Profile(2025,player,teams,games,rows,coverage,"REG","C");
Check(a.Groups["passing"]!.Totals["passing_yards"]==100&&a.AllTeamGroups["passing"]!.TeamContributions.Length==2,"Filter actual contributions, retain all-team breakdown");
Check(NflSeasonInsights.Profile(2025,player,teams,games,rows,coverage,"POST",null).Groups["passing"]!.Totals["passing_yards"]==10,"Postseason separate");
var diff=NflSeasonInsights.Differences(a,c,"passing");Check(diff["passing_yards"]==20&&diff["completionPercentage"]==10,"Differences use values and percentage points");
var missing=rows.Select((r,i)=>i==0?Stat("g1",1,"A","B",10,7,null,"p"):r).ToArray();
var unknown=NflSeasonInsights.Profile(2025,player,teams,games,missing,coverage,"REG",null);
Check(unknown.Groups["passing"]!.Totals["passing_yards"]==null&&unknown.Groups["passing"]!.Rates["yardsPerAttempt"]==null,"Missing component keeps season total/rate unknown");
Check(NflSeasonInsights.Differences(unknown,c,"passing")["passing_yards"]==null,"Unknown comparison stays unknown");
var teamRows=new[]{Stat("g1",1,"A","B",10,7,100),Stat("g1",1,"B","A",10,6,60),Stat("g2",2,"C","A",10,8,80)};
var original=teamRows.Select(r=>r.PlayerId).ToArray();
var all=NflSeasonInsights.Teams(2025,teams,games,teamRows,"REG");var t=all.Single(t=>t.Team.TeamId=="A");
Check(t.Offense["passing"]!.Totals["passing_yards"]==100,"Own team production");
Check(t.Opponents["passing"]!.Totals["passing_yards"]==140,"Opponent production from opposing rows");
Check(t.ObservedTeamGames==1&&t.ObservedOpponentGames==2&&t.MissingTeamGames==1&&t.MissingOpponentGames==0,"Independent coverage");
Check(t.HomeAway[0].CompletedGames==1&&t.HomeAway[1].CompletedGames==1,"Designated home-away split");
Check(t.Weeks.Length==3&&t.Weeks[2].Record.CompletedGames==0,"Weekly trends retain future schedules without scores");
Check(teamRows.Select(r=>r.PlayerId).SequenceEqual(original),"Temporary team projection never mutates source");
var errors=0;try{NflSeasonInsights.Phase("PRE");}catch(NflDataException e){if(e.StatusCode==400)errors++;}try{NflSeasonInsights.Group("defense");}catch(NflDataException e){if(e.StatusCode==400)errors++;}Check(errors==2,"Unsupported insight filters rejected");
Console.WriteLine($"{checks} NFL season insight calculation checks passed");
